      type: "SYNC_FULL",
      stateID: fullState.ctx._stateID,
      canUndo: this.canUndoForRecipient(playerId),
      state: fullState,
      protocolVersion: PROTOCOL_VERSION,
      matchID: fullState.ctx.matchID,
