    playerId: string,
    zone: "discard" | "hand" | "play",
  ): CardInstanceId[] {
    const playerBoard = this.getBoard().players[playerId];
    if (!playerBoard) {
      return [];
    }

    const zoneCards =
      zone === "discard"
        ? playerBoard.discard
        : zone === "hand"
          ? playerBoard.hand
          : playerBoard.play;

    return zoneCards.map((id) => id as CardInstanceId);
