  private getPendingActionPayload(pendingEffect: EnginePendingEffectProjection):
    | {
        id?: string;
        sourceCardId?: string;
        sourceId?: string;
        chooserId?: string;
      }
    | undefined {
    const payload = pendingEffect.payload;
    if (!payload || typeof payload !== "object") {
      return undefined;
    }

    return payload as {
      id?: string;
      sourceCardId?: string;
      sourceId?: string;
      chooserId?: string;
    };
  }

